bash -c 'source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && echo "=== SPATIAL TRAINED ===" && python3 << '"'"'PYEOF'"'"'
import json
for fname in ["action_r2_probing","l1_attention_profile","cross_instruction_classification","counterfactual_combined"]:
    path = f"/root/autodl-tmp/vla-ssd/results/tracvla_spatial/trained/{fname}.json"
    try:
        d = json.load(open(path))
        if fname == "action_r2_probing":
            for pos in d:
                vals = d[pos]
                keys = sorted(vals.keys(), key=lambda x: int(x.split("_")[-1]) if "_" in x else int(x[1:]))
                peak_k = max(vals, key=vals.get)
                last_k = keys[-1]
                for lk in keys:
                    ln = int(lk.split("_")[-1]) if "_" in lk else int(lk[1:])
                    if ln in [0,4,8,12,16,20,24,28,31]:
                        print(f"  {pos} {lk}: {vals[lk]:.4f}")
                print(f"  {pos} PEAK: {vals[peak_k]:.4f} @ {peak_k}")
                print(f"  {pos} LAST: {vals[last_k]:.4f} @ {last_k}")
        elif fname == "l1_attention_profile":
            ratios = d.get("per_head_instruction_ratio", d)
            instr = sum(1 for v in ratios.values() if float(v) > 0.5)
            total = len(ratios)
            print(f"  L1: {instr}/{total} instruction-dominant")
            top = sorted(ratios.items(), key=lambda x: float(x[1]), reverse=True)[:3]
            print(f"  Top: {[(k,round(float(v),3)) for k,v in top]}")
        elif fname == "cross_instruction_classification":
            vals = list(d.values())
            print(f"  Cross-instr: first={vals[0]:.4f}, last={vals[-1]:.4f}, min={min(vals):.4f}")
        elif fname == "counterfactual_combined":
            for k,v in d.items():
                if isinstance(v, dict):
                    cd = v.get("cos_dist_mean", v.get("cos_dist", "?"))
                    dd = v.get("cohens_d", "?")
                    ctm = v.get("cross_task_mean_d", "?")
                    print(f"  {k}: cos_dist={cd}, d={dd}, cross_task_d={ctm}")
        print(f"--- {fname} OK ---")
    except Exception as e:
        print(f"--- {fname} ERROR: {e} ---")
PYEOF'

